// AuditEntry defines model for AuditEntry.
type AuditEntry struct {
	Action string    `json:"action"`
	At     time.Time `json:"at"`

	// Detail What the action changed, per action; `error` on a failure. Never secret values.
	Detail map[string]interface{} `json:"detail"`
	Id     int64                  `json:"id"`

	// InstanceId The Pi-hole instance, for actions about one. Absent otherwise, or once the instance is deleted.
	InstanceId *int64 `json:"instance_id,omitempty"`

	// InstanceName The instance's name at the time, kept after it is deleted; empty when there is none.
	InstanceName string `json:"instance_name"`

	// Ip The client address, or empty for the CLI and the app itself.
	Ip     string           `json:"ip"`
	Result AuditEntryResult `json:"result"`

	// Target What the action was performed against, or empty.
	Target string `json:"target"`

	// UserId The acting user's ID. Absent when there was no user row (a failed login with an unknown name, the CLI or the app itself) or the user has since been deleted.
	UserId *int64 `json:"user_id,omitempty"`

	// Username The acting user, the name typed into a failed login, `(cli)` for the command line or `(system)` for the app itself.
	Username string `json:"username"`
}

// AuditEntryResult defines model for AuditEntry.Result.
type AuditEntryResult string

// AuditList defines model for AuditList.
type AuditList struct {
	Entries []AuditEntry `json:"entries"`

	// NextCursor Pass as `cursor` for the next page. Absent on the last page.
	NextCursor *string `json:"next_cursor,omitempty"`
}

// BlockingInput defines model for BlockingInput.
type BlockingInput struct {
	Enabled bool `json:"enabled"`

	// Timer Only with `enabled` false. Seconds until Pi-hole turns blocking back on. Leaving it out when disabling needs `blocking.indefinite` as well as `blocking.toggle`.
	Timer *int `json:"timer,omitempty"`
}

// BlockingStatus defines model for BlockingStatus.
type BlockingStatus struct {
	// Blocking failed and unknown mean Pi-hole couldn't tell. mixed is only for a mirrored group whose members differ.
	Blocking BlockingStatusBlocking `json:"blocking"`

	// Timer Seconds until blocking changes back, rounded up. Absent when no timer is running. For a mirrored group, the soonest of its members' timers.
	Timer *int `json:"timer,omitempty"`
}

// BlockingStatusBlocking failed and unknown mean Pi-hole couldn't tell. mixed is only for a mirrored group whose members differ.
type BlockingStatusBlocking string

// BlockingWriteResult defines model for BlockingWriteResult.
type BlockingWriteResult struct {
	// Blocking Present when ok.
	Blocking *BlockingStatus `json:"blocking,omitempty"`

	// Error Why an instance failed or was skipped. Present exactly when the status isn't ok.
	Error *WriteError `json:"error,omitempty"`

	// Instance The instance's name.
	Instance   string `json:"instance"`
	InstanceId int64  `json:"instance_id"`

	// Status ok: the change was made. failed: the Pi-hole was asked and the change failed (see `error`). skipped: the instance wasn't asked, because it was found down moments ago or can't be used (see `error`).
	Status WriteStatus `json:"status"`
}

// BlockingWriteResults The result per instance of turning blocking on or off.
type BlockingWriteResults struct {
	Results []BlockingWriteResult `json:"results"`
}

